cases.source_utf8:
@charset "utf-8";
@import url("base.css") screen;
@namespace svg url("http://www.w3.org/2000/svg");

:root {
  --accent: #3366ff;
  --gap: calc(1rem + 2px);
}

/* Layout */
body > main .card:hover,
#top::before {
  display: flex;
  margin: 0 auto !important;
  color: var(--accent, blue);
  background: linear-gradient(to right, rgb(0 0 0 / 50%), transparent);
}

a[href^="https"]:not(.internal) ~ span + em {
  font: italic bold 12px/1.5 "Helvetica Neue", sans-serif;
}

@media screen and (min-width: 600px) {
  .grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@supports (display: grid) {
  .grid { gap: var(--gap); }
}

@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@font-face {
  font-family: "Inter";
  src: url("inter.woff2") format("woff2");
}

edits.replace:
  font: italic bold 12px/1.5 "Helvetica Neue", sans-serif;
}

.hidden { display: none; }

